import { Group, Mesh, PlaneGeometry, Color, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'home-subhead';

  const inner = new Group();
  root.add(inner);

  const specColors = config.intent?.visualSpec?.colors ?? {};
  const inkHex = specColors.ink ?? '#16161d';
  const paperHex = specColors.paper ?? '#e8ecf2';
  const accentHex = specColors.accent ?? '#ff2a38';
  const surfaceHex = specColors.surface ?? '#0b0b10';

  const ink = new Color(inkHex);
  const surface = new Color(surfaceHex);

  /* ── Backdrop gradient plane (z = -2.5) ── */
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false
  });
  const vUV = uv();
  backdropMat.colorNode = mix(
    vec3(surface.r, surface.g, surface.b),
    vec3(ink.r, ink.g, ink.b),
    smoothstep(float(0.0), float(1.0), vUV.y)
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  inner.add(backdrop);

  /* ── Main image plane (512:320 aspect) ── */
  const planeW = 4.4;
  const planeH = planeW * (320 / 512);
  const planeGeo = new PlaneGeometry(planeW, planeH);
  const planeMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide
  });

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }
  const planeMesh = new Mesh(planeGeo, planeMat);
  planeMesh.position.set(0, 0, 0);
  inner.add(planeMesh);

  /* ── Subtle frame border on the plane ── */
  const frameGeo = new PlaneGeometry(planeW + 0.03, planeH + 0.03);
  const frameMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false
  });
  frameMat.colorNode = vec3(ink.r * 1.4, ink.g * 1.4, ink.b * 1.4);
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.set(0, 0, -0.005);
  inner.add(frame);

  /* ── Text overlay via MSDF fontAtlas ── */
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item.text) continue;
    const fontSize = item.typography?.fontSize ?? 42;
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSize,
      color: paperHex,
      align: 'center',
      maxWidthPx: 480,
      letterSpacingPx: 1
    });
    textObj.position.set(0, -0.04, 0.03);
    inner.add(textObj);
  }

  /* ── Accent signal line ── */
  const accentGeo = new PlaneGeometry(0.5, 0.015);
  const accentMat = new MeshBasicNodeMaterial({
    transparent: true,
    color: accentHex,
    side: DoubleSide
  });
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.set(0, -0.2, 0.02);
  inner.add(accentLine);

  /* ── Entrance animation (rise-in + weighted-settle) ── */
  const tl = gsap.timeline();
  tl.from(inner.position, { y: 0.4, duration: 0.7, ease: 'power3.out' });
  tl.from(inner.scale, { x: 0.96, y: 0.96, duration: 0.7, ease: 'power3.out' }, 0);
  tl.from(backdropMat, { opacity: 0, duration: 0.6, ease: 'power2.out' }, 0);
  tl.from(planeMat, { opacity: 0, duration: 0.6, ease: 'power2.out' }, 0.1);
  tl.from(accentMat, { opacity: 0, duration: 0.4, ease: 'power2.out' }, 0.3);
  tl.to(inner.scale, { x: 1.04, y: 1.04, duration: 0.45, ease: 'power2.out' }, 0.55);
  tl.to(inner.scale, { x: 1, y: 1, duration: 0.9, ease: 'power4.out' }, 1.0);

  /* ── Cleanup ── */
  root.userData.cleanup = () => {
    tl.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    planeGeo.dispose();
    planeMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
  };

  root.userData.handlers = {};

  return root;
}
